def buy_ioc_snapshot(asks,quantity,limit_cents):
    if type(quantity) is not int or not 1<=quantity<=1000000:
        raise ValueError("expected bounded positive integer quantity")
    if type(limit_cents) is not int or not 1<=limit_cents<=1000000:
        raise ValueError("expected bounded positive integer limit cents")
    if type(asks) is not list or len(asks)>1000:
        raise ValueError("expected at most1000ask levels")
    if any(type(row) is not tuple or len(row)!=2 or
           any(type(v) is not int or not 1<=v<=1000000 for v in row) for row in asks):
        raise ValueError("expected positive integer(price,size)tuples")
    if any(asks[i][0]>=asks[i+1][0] for i in range(len(asks)-1)):
        raise ValueError("expected strictly increasing distinct ask prices")
    remaining = quantity
    fills = []
    for price,size in asks:
        if price>limit_cents or remaining==0:
            break
        take = min(size,remaining)
        fills.append((price,take))
        remaining -= take
    # Unfilled remainder is canceled by this synthetic IOC policy, never rested.
    return fills,remaining,sum(price*size for price,size in fills)

book = [(1001,3),(1002,4),(1004,5)]
print(buy_ioc_snapshot(book,10,1002))
print(book)
