def displayed_priority(orders,side):
    if side not in ("buy","sell"):
        raise ValueError("expected buy or sell")
    if type(orders) is not list or len(orders)>1000:
        raise ValueError("expected at most1000orders")
    ids=set();sequences=set()
    for row in orders:
        if type(row) is not tuple or len(row)!=4:
            raise ValueError("expected(id,price,size,arrival_sequence)")
        oid,price,size,sequence=row
        if type(oid) is not str or not oid or len(oid)>20 or oid in ids:
            raise ValueError("expected unique short nonempty string ids")
        if any(type(v) is not int or not 1<=v<=1000000 for v in (price,size,sequence)) or sequence in sequences:
            raise ValueError("expected bounded positive ints and unique arrival sequence")
        ids.add(oid);sequences.add(sequence)
    sign=-1 if side=="buy" else 1
    return sorted(orders,key=lambda row:(sign*row[1],row[3]))

bids=[("A",1000,5,1),("B",1001,2,3),("C",1000,7,2)]
print([row[0] for row in displayed_priority(bids,"buy")])
asks=[("D",1003,5,1),("E",1002,3,4),("F",1003,2,2)]
print([row[0] for row in displayed_priority(asks,"sell")])
print(min(row[1] for row in asks)-max(row[1] for row in bids))
